<?php
const COURIER_NAMES=['pathao'=>'Pathao Courier','steadfast'=>'Steadfast Courier','manual'=>'Manual delivery'];
function delivery_rules():array{$defaults=['standard_enabled'=>true,'express_enabled'=>false,'pickup_enabled'=>false,'dhaka_fee'=>80,'suburbs_fee'=>100,'outside_fee'=>130,'express_extra'=>60,'pickup_address'=>'','eta_en'=>'3–5 business days','eta_bn'=>'৩–৫ কর্মদিবস','default_provider'=>'manual','poll_minutes'=>15];$v=json_decode(setting('delivery_rules','{}'),true)?:[];return array_replace($defaults,$v);}
function delivery_cost(int $subtotal,string $method,string $region):int{$d=delivery_rules();if(!in_array($region,['dhaka','suburbs','outside'],true))throw new RuntimeException('Choose a delivery region.');if(!in_array($method,['standard','express','pickup'],true)||empty($d[$method.'_enabled']))throw new RuntimeException('This delivery option is unavailable.');if($method==='pickup')return 0;$base=$subtotal>=(int)setting('free_shipping','3000')?0:(int)$d[$region.'_fee'];return $base+($method==='express'?(int)$d['express_extra']:0);}
function courier_config(string $p):array{if(!isset(COURIER_NAMES[$p]))throw new RuntimeException('Unsupported courier.');$v=json_decode(setting('courier_'.$p,'{}'),true)?:[];return array_replace(['enabled'=>false,'mode'=>'simulation','endpoint'=>'steadfast','store_id'=>0,'weight'=>0.5,'delivery_type'=>48,'item_type'=>2,'webhooks_enabled'=>false,'webhook_response_header'=>'X-Pathao-Merchant-Webhook-Integration-Secret'],$v);}
function courier_secrets(string $p):array{$enc=setting('private_courier_'.$p,'');return $enc?json_decode(secret_decrypt($enc),true)?:[]:[];}
function courier_fingerprint(string $p):string{$c=courier_config($p);$s=courier_secrets($p);unset($s['webhook_secret'],$s['webhook_response_value']);ksort($s);return hash('sha256',$p.'|'.$c['mode'].'|'.($c['endpoint']??'steadfast').'|'.json_encode($s));}
function courier_required(string $p):array{return $p==='pathao'?['client_id','client_secret','username','password']:['api_key','secret_key'];}
function courier_ready(string $p,bool $booking=false):void{global $demo;$c=courier_config($p);if($c['mode']==='simulation')return;$s=courier_secrets($p);foreach(courier_required($p)as $k)if(empty($s[$k]))throw new RuntimeException('Add your courier credentials and test the connection first.');if($booking){if(!$c['enabled'])throw new RuntimeException('Enable this courier before booking.');$h=json_decode(setting('private_courier_health_'.$p,'{}'),true)?:[];if(empty($h['ok'])||($h['fingerprint']??'')!==courier_fingerprint($p))throw new RuntimeException('Test the current courier credentials before booking.');if($c['mode']==='live'&&$demo)throw new RuntimeException('Live courier bookings are blocked while demo=true.');if($p==='pathao'&&(int)$c['store_id']<1)throw new RuntimeException('Select an active Pathao pickup store first.');}}
function courier_log(string $p,string $op,int $status,string $outcome,string $message,?int $sid=null):void{if(in_array($outcome,['failed','unknown','rejected']))record_error($message,['source'=>'courier','action'=>$op,'status'=>$status,'provider'=>$p,'operation'=>$op,'shipment_id'=>$sid??0]);query('INSERT INTO courier_logs(shipment_id,provider,operation,http_status,outcome,message) VALUES(?,?,?,?,?,?)',[$sid,$p,$op,$status,$outcome,mb_substr($message,0,700)]);}
