function pathao_token(bool $force=false):string{$key='private_pt_'.substr(courier_fingerprint('pathao'),0,40);$cached=json_decode(secret_decrypt(setting($key,'')),true)?:[];if(!$force&&!empty($cached['access_token'])&&($cached['expires_at']??0)>time()+90)return $cached['access_token'];$s=courier_secrets('pathao');$params=['client_id'=>$s['client_id'],'client_secret'=>$s['client_secret']];if(!empty($cached['refresh_token'])){$r=carrier_http('pathao','POST','/aladdin/api/v1/issue-token',$params+['grant_type'=>'refresh_token','refresh_token'=>$cached['refresh_token']]);}if(empty($r['ok']))$r=carrier_http('pathao','POST','/aladdin/api/v1/issue-token',$params+['grant_type'=>'password','username'=>$s['username'],'password'=>$s['password']]);if(!$r['ok']||empty($r['data']['access_token']))throw new RuntimeException('Pathao authentication failed. Check the selected environment and credentials.');$token=$r['data'];$token['expires_at']=time()+max(60,(int)($token['expires_in']??300));set_setting($key,secret_encrypt(json_encode($token)));return $token['access_token'];}
