function pathao_list(string $kind,int $parent=0):array{$path=match($kind){'stores'=>'/aladdin/api/v1/stores','cities'=>'/aladdin/api/v1/city-list','zones'=>'/aladdin/api/v1/cities/'.$parent.'/zone-list','areas'=>'/aladdin/api/v1/zones/'.$parent.'/area-list',default=>throw new RuntimeException('Unsupported location list.')};courier_ready('pathao');if(courier_config('pathao')['mode']==='simulation')return [];$r=carrier_request('pathao','GET',$path);if(!$r['ok'])throw new RuntimeException($r['message']);return $r['data']['data']['data']??$r['data']['data']??[];}
function provider_to_order_status(string $s):?string{$v=strtolower(str_replace(['_','-','.'],' ',$s));$v=preg_replace('/^order /','',$v);return match($v){'delivered'=>'Delivered','cancelled','canceled'=>'Cancelled','returned','return'=>'Returned','partial delivery','partial delivered'=>'Partially delivered','picked','picked up','in transit','at the sorting hub','at the delivery hub','assigned for delivery','out for delivery'=>'Shipped','created','pending','in review','pickup requested','assigned for pickup'=>'Processing',default=>null};}
function update_shipment_status(array $shipment,string $raw,?string $updated=null):void{global $db;$db->beginTransaction();$o=query('SELECT * FROM orders WHERE id=? FOR UPDATE',[$shipment['order_id']])->fetch();$s=query('SELECT * FROM shipments WHERE id=? FOR UPDATE',[$shipment['id']])->fetch();if(!$s){$db->rollBack();return;}try{$newTime=$updated?(new DateTimeImmutable($updated,new DateTimeZone('Asia/Dhaka')))->getTimestamp():false;}catch(Throwable $e){$newTime=false;}$oldTime=$s['provider_updated_at']?strtotime($s['provider_updated_at'].' UTC'):false;if($newTime&&$oldTime&&$newTime<$oldTime){$db->rollBack();return;}$mapped=provider_to_order_status($raw);$rank=['Pending'=>0,'Processing'=>1,'Shipped'=>2,'Partially delivered'=>3,'Delivered'=>4,'Returned'=>5,'Cancelled'=>5];if($mapped&&($rank[$mapped]??0)<($rank[$o['status']]??0))$mapped=null;$terminal=in_array($o['status'],['Delivered','Returned','Cancelled']);if($terminal&&$mapped&&$mapped!==$o['status']&&!in_array($mapped,['Returned']))$mapped=null;query('UPDATE shipments SET provider_status=?,last_sync_at=NOW(),provider_updated_at=COALESCE(?,provider_updated_at),last_error=?,error_code=? WHERE id=?',[mb_substr($raw,0,100),$newTime?gmdate('Y-m-d H:i:s',$newTime):null,'','',$s['id']]);$changed=$mapped&&$mapped!==$o['status'];if($changed){if($mapped==='Delivered')query('UPDATE orders SET delivered_at=COALESCE(delivered_at,?) WHERE id=?',[$newTime&&$newTime<=time()+300&&$newTime>=strtotime($o['created_at'].' UTC')?gmdate('Y-m-d H:i:s',$newTime):gmdate('Y-m-d H:i:s'),$o['id']]);query('UPDATE orders SET status=? WHERE id=?',[$mapped,$o['id']]);query('INSERT INTO order_events(order_id,status,note) VALUES(?,?,?)',[$o['id'],$mapped,COURIER_NAMES[$s['provider']].': '.$raw]);}$db->commit();if($changed){emit_event('order-status','user',['order_id'=>(int)$o['id'],'status'=>$mapped],(int)$o['user_id']);emit_event('order-updated','admin',['order_id'=>(int)$o['id'],'status'=>$mapped]);}}
function sync_shipment(array $s):array{if(in_array($s['mode'],['simulation','manual']))return ['ok'=>true,'message'=>'Local simulation or manual shipment.'];if($s['account_fingerprint']!==courier_fingerprint($s['provider']))throw new RuntimeException('Courier account or environment changed. Restore the original account before syncing.');if(!$s['consignment_id'])throw new RuntimeException('A consignment ID is required. Reconcile this booking first.');$r=$s['provider']==='pathao'?carrier_request('pathao','GET','/aladdin/api/v1/orders/'.rawurlencode($s['consignment_id']).'/info'):carrier_request('steadfast','GET','/status_by_cid/'.rawurlencode($s['consignment_id']));if(!$r['ok']){courier_log($s['provider'],'status-sync',$r['status'],'failed',$r['message'],(int)$s['id']);query('UPDATE shipments SET last_error=?,last_sync_at=NOW() WHERE id=?',[$r['message'],$s['id']]);throw new RuntimeException($r['message']);}$raw=$s['provider']==='pathao'?($r['data']['data']['order_status_slug']??$r['data']['data']['order_status']??''):($r['data']['delivery_status']??$r['data']['status_name']??'');if(!is_string($raw)||$raw==='')throw new RuntimeException('Courier returned no recognizable delivery status.');update_shipment_status($s,$raw,$r['data']['data']['updated_at']??null);return ['ok'=>true,'status'=>$raw];}
function shipment_payload(array $order,string $provider,array $in):array{$c=courier_config($provider);$name=trim($in['recipient_name']??$order['name']);$address=trim($in['recipient_address']??$order['address']);$phone=phone_normalize($in['recipient_phone']??$order['phone']);$limit=$provider==='pathao'?220:250;if(mb_strlen($name)<3||mb_strlen($name)>100||mb_strlen($address)<10||mb_strlen($address)>$limit)throw new RuntimeException('Courier requires a 3–100 character recipient name and a 10–'.$limit.' character address.');$note=mb_substr(trim($in['note']??''),0,300);$weight=(float)($in['weight']??$c['weight']);if($weight<0.5||$weight>10)throw new RuntimeException('Parcel weight must be 0.5–10 kg.');$qty=(int)($in['quantity']??1);if($qty<1||$qty>20)throw new RuntimeException('Use 1–20 parcels.');$ref='BN-'.$order['id'].'-'.substr(hash('sha256',$order['tracking_token']),0,8);$desc=implode(', ',array_map(fn($l)=>$l['quantity'].'x '.$l['name'],query('SELECT name,quantity FROM order_items WHERE order_id=?',[$order['id']])->fetchAll()));
