ight'],json_encode($payload['payload'],JSON_UNESCAPED_UNICODE)]);$sid=(int)$db->lastInsertId();if(in_array($state,['simulated','manual'])){$cid=$mode==='manual'?trim($in['tracking_code']??''):'DEMO-'.strtoupper(substr($provider,0,2)).'-'.$sid;query('UPDATE shipments SET consignment_id=?,tracking_code=?,provider_status=? WHERE id=?',[$cid,$cid,$mode==='manual'?'Manual dispatch':'Simulated booking',$sid]);query('UPDATE orders SET courier=?,tracking_number=? WHERE id=?',[COURIER_NAMES[$provider].($mode==='simulation'?' (demo)':''),$cid,$oid]);}$db->commit();courier_log($provider,'dispatch',0,$state,$mode==='simulation'?'Local simulation created. No courier API contacted.':($mode==='manual'?'Manual delivery recorded. No courier API contacted.':'Booking intent saved. Waiting for the dispatch worker.'),$sid);audit('courier-booking-queued',['shipment_id'=>$sid,'provider'=>$provider,'mode'=>$mode]);emit_event('order-updated','admin',['order_id'=>$oid,'status'=>'Shipment '.$state]);return ['id'=>$sid,'state'=>$state,'mode'=>$mode];}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}
